<div class="intro-line"><p>Akun, koperasi yang diwakili, dan perannya dikelola di sini. Hanya superadmin yang dapat mengubah hak akses.</p><div class="page-actions"><a class="button button-quiet" href="<?= site_url('admin/peran') ?>">Peran & izin</a><a class="button button-dark" href="<?= site_url('admin/pengguna/tambah') ?>">+ Tambah pengguna</a></div></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari pengguna</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nama, akun, atau email"></label><label><span>Peran</span><select name="role"><option value="">Semua</option><?php foreach ($roles as $r): ?><option value="<?= $r['id'] ?>" <?= (string)$role===(string)$r['id']?'selected':'' ?>><?= h($r['name']) ?></option><?php endforeach; ?></select></label><label><span>Status</span><select name="status"><option value="">Semua</option><option value="aktif" <?= $p['status']==='aktif'?'selected':'' ?>>Aktif</option><option value="arsip" <?= $p['status']==='arsip'?'selected':'' ?>>Nonaktif</option></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Pengguna</th><th>Peran</th><th>Koperasi</th><th>Status</th><th>Masuk terakhir</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><strong><?= h($r['full_name']) ?></strong><small class="cell-sub mono">@<?= h($r['username']) ?><?= $r['email']?' · '.h($r['email']):'' ?></small></td><td><?= h($r['role_names']) ?></td><td><?= h($r['cooperative_name']?:'—') ?></td><td><span class="pill <?= $r['active']?'pill-green':'pill-muted' ?>"><?= $r['active']?'Aktif':'Nonaktif' ?></span></td><td><?= $r['last_login_at']?h(date('d M Y H:i',strtotime($r['last_login_at']))):'—' ?></td><td><a class="row-link" href="<?= site_url('admin/pengguna/'.$r['id'].'/ubah') ?>">Ubah →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6" class="empty-cell">Tidak ada pengguna yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
